const icon=(name,cls="")=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.wallet}</svg>`;
const esc=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const money=value=>`${Math.round(value).toLocaleString("vi-VN")} ₫`;
const short=value=>`${(value/1e6).toLocaleString("vi-VN",{maximumFractionDigits:1})}tr`;
const percent=value=>`${value.toLocaleString("vi-VN",{maximumFractionDigits:1})}%`;
const normalized=value=>String(value).normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/đ/g,"d").replace(/Đ/g,"D").toLowerCase();
const day=value=>value.split("-").reverse().join("/");
